import sys
import base64
import hashlib
import email.utils
import email.policy
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from email.mime.base import MIMEBase


def build_message(request):
    """Build a MIME email message from the request dictionary."""
    try:
        # Validate schema
        required_fields = {'from', 'to', 'subject', 'date', 'message_id', 'body', 'attachments'}
        if not isinstance(request, dict) or not all(k in request for k in required_fields):
            return None

        if not isinstance(request['from'], str):
            return None

        if not isinstance(request['to'], list) or not (1 <= len(request['to']) <= 8):
            return None
        if not all(isinstance(t, str) for t in request['to']):
            return None

        if not isinstance(request['subject'], str) or not request['subject']:
            return None

        if not isinstance(request['date'], int):
            return None

        if not isinstance(request['message_id'], str):
            return None

        if not isinstance(request['body'], str):
            return None

        if not isinstance(request['attachments'], list) or not (0 <= len(request['attachments']) <= 8):
            return None

        for attachment in request['attachments']:
            if not isinstance(attachment, dict):
                return None
            if 'filename' not in attachment or 'content_type' not in attachment or 'content_b64' not in attachment:
                return None
            if not isinstance(attachment['filename'], str) or not attachment['filename']:
                return None
            if '/' in attachment['filename'] or '\\' in attachment['filename']:
                return None
            if not isinstance(attachment['content_type'], str):
                return None
            if not isinstance(attachment['content_b64'], str):
                return None

        # Build the MIME message with deterministic policy
        policy = email.policy.EmailPolicy(
            utf8=False,
            max_line_length=998,
            linesep='\n',
        )
        msg = MIMEMultipart('mixed', policy=policy)

        # Set headers
        msg['From'] = request['from']
        msg['To'] = request['to']
        msg['Subject'] = request['subject']
        msg['Date'] = email.utils.format_datetime(request['date'], localtime=False)
        msg['Message-ID'] = request['message_id']
        msg['MIME-Version'] = '1.0'

        # RFC 2047 encode subject if non-ASCII
        subject_bytes = request['subject'].encode('utf-8')
        if any(c > 127 for c in subject_bytes):
            subject_encoded = email.utils.make_header(request['subject']).encode('ascii')
            msg['Subject'] = subject_encoded

        # Attach body as text/plain with utf-8 charset
        body_part = MIMEText(request['body'], 'utf-8')
        msg.attach(body_part)

        # Attachments
        for attachment in request['attachments']:
            content = base64.b64decode(attachment['content_b64'])

            attachment_part = MIMEBase(attachment['content_type'])
            attachment_part.set_payload(content, charset=None)

            # RFC 2231 filename encoding
            filename = attachment['filename']
            try:
                filename.encode('ascii')
            except UnicodeEncodeError:
                charset = 'utf-8'
                filename_bytes = filename.encode(charset)
                filename_param = f"{charset}'en'{filename_bytes.hex()}"
                attachment_part.add_header('Content-Disposition', 'attachment', filename=filename_param)
            else:
                attachment_part.add_header('Content-Disposition', 'attachment', filename=filename)

            attachment_part['Content-Transfer-Encoding'] = 'base64'
            msg.attach(attachment_part)

        # Generate message bytes
        message_bytes = msg.as_bytes()

        return message_bytes

    except Exception:
        return None


def main():
    try:
        raw_input = sys.stdin.read()
        request = json.loads(raw_input)
    except (json.JSONDecodeError, ValueError, UnicodeDecodeError):
        print(json.dumps({"error": "invalid_request"}))
        return

    message_bytes = build_message(request)
    if message_bytes is None:
        print(json.dumps({"error": "invalid_request"}))
        return

    message_b64 = base64.b64encode(message_bytes).decode('ascii')
    sha256 = hashlib.sha256(message_bytes).hexdigest()

    print(json.dumps({
        "format": "eml",
        "message_b64": message_b64,
        "sha256": sha256
    }))


if __name__ == '__main__':
    main()"}

